var quick_start_default = "---\nlayout: article\ntitle: Start with VectorsDB\ndescription: Get started with Appwrite VectorsDB. Follow a step-by-step guide to create your first database, add a collection with a fixed dimension, store embeddings with metadata, and read them back.\n---\n\n\nVectorsDB stores embedding vectors so you can build features like semantic search, recommendations, and retrieval for AI applications.\nThis guide walks through creating a database, adding a collection with a fixed `dimension`, storing a document with its `embeddings` and `metadata`, and reading it back.\n\nThese steps use a [Server SDK](/docs/sdks#server), which requires an [API key](/docs/advanced/platform/api-keys).\n\n{% section #create-database step=1 title=\"Create database\" %}\nHead to your [Appwrite Console](https://cloud.appwrite.io/console/) and click **Create database**. Name it `Knowledge base` and choose **VectorsDB** as the database type.\nOptionally, add a custom database ID. Select your preferred tier, then click **Create database**.\n\nYou can also create a database programmatically with the `create` method.\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.create({\n    databaseId: sdk.ID.unique(),\n    name: 'Knowledge base'\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.create({\n    databaseId: sdk.ID.unique(),\n    name: 'Knowledge base'\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\ID;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$result = $vectorsDB->create(\n    databaseId: ID::unique(),\n    name: 'Knowledge base'\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.id import ID\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\nresult = vectors_db.create(\n    database_id = ID.unique(),\n    name = 'Knowledge base'\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\nresult = vectors_db.create(\n    database_id: ID.unique(),\n    name: 'Knowledge base'\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Models;\nusing Appwrite.Services;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nDatabase result = await vectorsDB.Create(\n    databaseId: ID.Unique(),\n    name: \"Knowledge base\"\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nDatabase result = await vectorsDB.create(\n    databaseId: ID.unique(),\n    name: 'Knowledge base',\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.ID\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval response = vectorsDB.create(\n    databaseId = ID.unique(),\n    name = \"Knowledge base\",\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.ID;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvectorsDB.create(\n    ID.unique(),\n    \"Knowledge base\",\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet database = try await vectorsDB.create(\n    databaseId: ID.unique(),\n    name: \"Knowledge base\"\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::id::ID;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let result = vectors_db.create(\n        ID::unique(),\n        \"Knowledge base\",\n        None, // enabled (optional)\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db create \\\n    --database-id <DATABASE_ID> \\\n    --name \"Knowledge base\"\n```\n{% /multicode %}\n{% /section %}\n\n{% section #create-collection step=2 title=\"Create collection\" %}\nIn the `Knowledge base` database, click **Create collection** and name it `Articles`. Optionally, add a custom collection ID.\n\nA VectorsDB collection has a fixed `dimension`, the length of the embedding vectors it holds. All documents in the collection must use vectors of that exact length, so set the `dimension` to match the embedding model you plan to use. This guide uses `dimension: 4` to keep the vectors short and readable. The default `nomic-embed-text` [embedding model](/docs/products/databases/vectorsdb/embeddings) produces 768-dimensional vectors, so a production collection would use `dimension: 768`.\n\nThe schema is provisioned for you: an `embeddings` vector and an optional `metadata` object. There are no columns to define.\n\nSet the **dimension**, then add a **Read** permission for the **Any** role so anyone can read documents.\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createCollection({\n    databaseId: '<DATABASE_ID>',\n    collectionId: sdk.ID.unique(),\n    name: 'Articles',\n    dimension: 4,\n    permissions: [sdk.Permission.read(sdk.Role.any())] // optional\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createCollection({\n    databaseId: '<DATABASE_ID>',\n    collectionId: sdk.ID.unique(),\n    name: 'Articles',\n    dimension: 4,\n    permissions: [sdk.Permission.read(sdk.Role.any())] // optional\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\ID;\nuse Appwrite\\Permission;\nuse Appwrite\\Role;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$result = $vectorsDB->createCollection(\n    databaseId: '<DATABASE_ID>',\n    collectionId: ID::unique(),\n    name: 'Articles',\n    dimension: 4,\n    permissions: [Permission::read(Role::any())] // optional\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.id import ID\nfrom appwrite.permission import Permission\nfrom appwrite.role import Role\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\nresult = vectors_db.create_collection(\n    database_id = '<DATABASE_ID>',\n    collection_id = ID.unique(),\n    name = 'Articles',\n    dimension = 4,\n    permissions = [Permission.read(Role.any())] # optional\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\ninclude Appwrite::Permission\ninclude Appwrite::Role\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\nresult = vectors_db.create_collection(\n    database_id: '<DATABASE_ID>',\n    collection_id: ID.unique(),\n    name: 'Articles',\n    dimension: 4,\n    permissions: [Permission.read(Role.any())] # optional\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Models;\nusing Appwrite.Services;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nCollection result = await vectorsDB.CreateCollection(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: ID.Unique(),\n    name: \"Articles\",\n    dimension: 4,\n    permissions: new List<string> { Permission.Read(Role.Any()) } // optional\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nCollection result = await vectorsDB.createCollection(\n    databaseId: '<DATABASE_ID>',\n    collectionId: ID.unique(),\n    name: 'Articles',\n    dimension: 4,\n    permissions: [Permission.read(Role.any())], // optional\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.ID\nimport io.appwrite.Permission\nimport io.appwrite.Role\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval response = vectorsDB.createCollection(\n    databaseId = \"<DATABASE_ID>\",\n    collectionId = ID.unique(),\n    name = \"Articles\",\n    dimension = 4,\n    permissions = listOf(Permission.read(Role.any())), // optional\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.ID;\nimport io.appwrite.Permission;\nimport io.appwrite.Role;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\nimport java.util.List;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvectorsDB.createCollection(\n    \"<DATABASE_ID>\",\n    ID.unique(),\n    \"Articles\",\n    4,\n    List.of(Permission.read(Role.any())),\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet collection = try await vectorsDB.createCollection(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: ID.unique(),\n    name: \"Articles\",\n    dimension: 4,\n    permissions: [Permission.read(Role.any())] // optional\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::id::ID;\nuse appwrite::permission::Permission;\nuse appwrite::role::Role;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let result = vectors_db.create_collection(\n        \"<DATABASE_ID>\",\n        ID::unique(),\n        \"Articles\",\n        4,\n        Some(vec![Permission::read(Role::any()).to_string()]), // permissions (optional)\n        None, // documentSecurity (optional)\n        None, // enabled (optional)\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db create-collection \\\n    --database-id <DATABASE_ID> \\\n    --collection-id <COLLECTION_ID> \\\n    --name \"Articles\" \\\n    --dimension 4 \\\n    --permissions 'read(\"any\")'\n```\n{% /multicode %}\n{% /section %}\n\n{% section #store-documents step=3 title=\"Store documents\" %}\nA document's data is an `embeddings` vector and an optional `metadata` object.\nThe `embeddings` array length must equal the collection's `dimension`, and `metadata` is free-form JSON you can use to store any data you want to keep alongside the vector.\n\nThe vectors here are hardcoded so the example runs on its own. In an application, you generate them from your text with [embeddings](/docs/products/databases/vectorsdb/embeddings).\n\nUse the `createDocument` method to store the embedding and its metadata.\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createDocument({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: sdk.ID.unique(),\n    data: {\n        embeddings: [0.12, 0.84, 0.33, 0.57],\n        metadata: { title: 'Getting started with Appwrite', tags: ['guide'] }\n    }\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.createDocument({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: sdk.ID.unique(),\n    data: {\n        embeddings: [0.12, 0.84, 0.33, 0.57],\n        metadata: { title: 'Getting started with Appwrite', tags: ['guide'] }\n    }\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\ID;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$result = $vectorsDB->createDocument(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: ID::unique(),\n    data: [\n        'embeddings' => [0.12, 0.84, 0.33, 0.57],\n        'metadata' => ['title' => 'Getting started with Appwrite', 'tags' => ['guide']]\n    ]\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.id import ID\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\nresult = vectors_db.create_document(\n    database_id = '<DATABASE_ID>',\n    collection_id = '<COLLECTION_ID>',\n    document_id = ID.unique(),\n    data = {\n        \"embeddings\": [0.12, 0.84, 0.33, 0.57],\n        \"metadata\": { \"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"] }\n    }\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\nresult = vectors_db.create_document(\n    database_id: '<DATABASE_ID>',\n    collection_id: '<COLLECTION_ID>',\n    document_id: ID.unique(),\n    data: {\n        \"embeddings\" => [0.12, 0.84, 0.33, 0.57],\n        \"metadata\" => { \"title\" => \"Getting started with Appwrite\", \"tags\" => [\"guide\"] }\n    }\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Models;\nusing Appwrite.Services;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nDocument result = await vectorsDB.CreateDocument(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    documentId: ID.Unique(),\n    data: new Dictionary<string, object> {\n        { \"embeddings\", new List<double> { 0.12, 0.84, 0.33, 0.57 } },\n        { \"metadata\", new Dictionary<string, object> { { \"title\", \"Getting started with Appwrite\" }, { \"tags\", new List<string> { \"guide\" } } } }\n    }\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nDocument result = await vectorsDB.createDocument(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    documentId: ID.unique(),\n    data: {\n        \"embeddings\": [0.12, 0.84, 0.33, 0.57],\n        \"metadata\": { \"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"] }\n    },\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.ID\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval response = vectorsDB.createDocument(\n    databaseId = \"<DATABASE_ID>\",\n    collectionId = \"<COLLECTION_ID>\",\n    documentId = ID.unique(),\n    data = mapOf(\n        \"embeddings\" to listOf(0.12, 0.84, 0.33, 0.57),\n        \"metadata\" to mapOf(\"title\" to \"Getting started with Appwrite\", \"tags\" to listOf(\"guide\"))\n    ),\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.ID;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\nimport java.util.List;\nimport java.util.Map;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvectorsDB.createDocument(\n    \"<DATABASE_ID>\",\n    \"<COLLECTION_ID>\",\n    ID.unique(),\n    Map.of(\n        \"embeddings\", List.of(0.12, 0.84, 0.33, 0.57),\n        \"metadata\", Map.of(\"title\", \"Getting started with Appwrite\", \"tags\", List.of(\"guide\"))\n    ),\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet document = try await vectorsDB.createDocument(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    documentId: ID.unique(),\n    data: [\n        \"embeddings\": [0.12, 0.84, 0.33, 0.57],\n        \"metadata\": [\"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"]]\n    ]\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::id::ID;\nuse serde_json::json;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let result = vectors_db.create_document(\n        \"<DATABASE_ID>\",\n        \"<COLLECTION_ID>\",\n        ID::unique(),\n        json!({\n            \"embeddings\": [0.12, 0.84, 0.33, 0.57],\n            \"metadata\": { \"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"] }\n        }),\n        None, // permissions (optional)\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db create-document \\\n    --database-id <DATABASE_ID> \\\n    --collection-id <COLLECTION_ID> \\\n    --document-id 'unique()' \\\n    --data '{ \"embeddings\": [0.12, 0.84, 0.33, 0.57], \"metadata\": { \"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"] } }'\n```\n{% /multicode %}\n\nThe response includes the stored `embeddings` and `metadata` alongside the document's system fields.\n\n```json\n{\n    \"embeddings\": [0.12, 0.84, 0.33, 0.57],\n    \"metadata\": { \"title\": \"Getting started with Appwrite\", \"tags\": [\"guide\"] },\n    \"$id\": \"6a43c07100195469a012\",\n    \"$sequence\": \"1\",\n    \"$createdAt\": \"2026-06-30T13:11:13.441+00:00\",\n    \"$updatedAt\": \"2026-06-30T13:11:13.441+00:00\",\n    \"$permissions\": [],\n    \"$databaseId\": \"650125c64b3c25ce4bc4\",\n    \"$collectionId\": \"650125cff227cf9f95ad\"\n}\n```\n{% /section %}\n\n{% section #read-documents step=4 title=\"Read documents\" %}\nTo read documents back from your collection, use the `listDocuments` method.\n\n{% multicode %}\n```server-nodejs\nconst sdk = require('node-appwrite');\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.listDocuments({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    queries: [\n        sdk.Query.limit(10)\n    ]\n});\n```\n```deno\nimport * as sdk from \"npm:node-appwrite\";\n\nconst client = new sdk.Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nconst vectorsDB = new sdk.VectorsDB(client);\n\nconst result = await vectorsDB.listDocuments({\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    queries: [\n        sdk.Query.limit(10)\n    ]\n});\n```\n```php\n<?php\n\nuse Appwrite\\Client;\nuse Appwrite\\Services\\VectorsDB;\nuse Appwrite\\Query;\n\n$client = (new Client())\n    ->setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    ->setProject('<YOUR_PROJECT_ID>') // Your project ID\n    ->setKey('<YOUR_API_KEY>'); // Your secret API key\n\n$vectorsDB = new VectorsDB($client);\n\n$result = $vectorsDB->listDocuments(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    queries: [\n        Query::limit(10)\n    ]\n);\n```\n```python\nfrom appwrite.client import Client\nfrom appwrite.services.vectors_db import VectorsDB\nfrom appwrite.query import Query\n\nclient = Client()\nclient.set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\nclient.set_project('<YOUR_PROJECT_ID>') # Your project ID\nclient.set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB(client)\n\nresult = vectors_db.list_documents(\n    database_id = '<DATABASE_ID>',\n    collection_id = '<COLLECTION_ID>',\n    queries = [\n        Query.limit(10)\n    ]\n)\n```\n```ruby\nrequire 'appwrite'\n\ninclude Appwrite\n\nclient = Client.new\n    .set_endpoint('https://<REGION>.cloud.appwrite.io/v1') # Your API Endpoint\n    .set_project('<YOUR_PROJECT_ID>') # Your project ID\n    .set_key('<YOUR_API_KEY>') # Your secret API key\n\nvectors_db = VectorsDB.new(client)\n\nresult = vectors_db.list_documents(\n    database_id: '<DATABASE_ID>',\n    collection_id: '<COLLECTION_ID>',\n    queries: [\n        Query.limit(10)\n    ]\n)\n```\n```csharp\nusing Appwrite;\nusing Appwrite.Models;\nusing Appwrite.Services;\nusing Appwrite.Queries;\n\nClient client = new Client()\n    .SetEndPoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .SetProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .SetKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nDocumentList result = await vectorsDB.ListDocuments(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    queries: new List<string> {\n        Query.Limit(10)\n    }\n);\n```\n```dart\nimport 'package:dart_appwrite/dart_appwrite.dart';\n\nClient client = Client()\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1') // Your API Endpoint\n    .setProject('<YOUR_PROJECT_ID>') // Your project ID\n    .setKey('<YOUR_API_KEY>'); // Your secret API key\n\nVectorsDB vectorsDB = VectorsDB(client);\n\nDocumentList result = await vectorsDB.listDocuments(\n    databaseId: '<DATABASE_ID>',\n    collectionId: '<COLLECTION_ID>',\n    queries: [\n        Query.limit(10)\n    ],\n);\n```\n```kotlin\nimport io.appwrite.Client\nimport io.appwrite.Query\nimport io.appwrite.services.VectorsDB\n\nval client = Client(context)\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nval vectorsDB = VectorsDB(client)\n\nval response = vectorsDB.listDocuments(\n    databaseId = \"<DATABASE_ID>\",\n    collectionId = \"<COLLECTION_ID>\",\n    queries = listOf(\n        Query.limit(10)\n    ),\n)\n```\n```java\nimport io.appwrite.Client;\nimport io.appwrite.Query;\nimport io.appwrite.coroutines.CoroutineCallback;\nimport io.appwrite.services.VectorsDB;\nimport java.util.List;\n\nClient client = new Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\"); // Your secret API key\n\nVectorsDB vectorsDB = new VectorsDB(client);\n\nvectorsDB.listDocuments(\n    \"<DATABASE_ID>\",\n    \"<COLLECTION_ID>\",\n    List.of(\n        Query.limit(10)\n    ),\n    new CoroutineCallback<>((result, error) -> {\n        if (error != null) {\n            error.printStackTrace();\n            return;\n        }\n\n        System.out.println(result);\n    })\n);\n```\n```swift\nimport Appwrite\n\nlet client = Client()\n    .setEndpoint(\"https://<REGION>.cloud.appwrite.io/v1\") // Your API Endpoint\n    .setProject(\"<YOUR_PROJECT_ID>\") // Your project ID\n    .setKey(\"<YOUR_API_KEY>\") // Your secret API key\n\nlet vectorsDB = VectorsDB(client)\n\nlet documents = try await vectorsDB.listDocuments(\n    databaseId: \"<DATABASE_ID>\",\n    collectionId: \"<COLLECTION_ID>\",\n    queries: [\n        Query.limit(10)\n    ]\n)\n```\n```server-rust\nuse appwrite::Client;\nuse appwrite::services::vectors_db::VectorsDB;\nuse appwrite::query::Query;\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let client = Client::new();\n    client.set_endpoint(\"https://<REGION>.cloud.appwrite.io/v1\"); // Your API Endpoint\n    client.set_project(\"<YOUR_PROJECT_ID>\"); // Your project ID\n    client.set_key(\"<YOUR_API_KEY>\"); // Your secret API key\n\n    let vectors_db = VectorsDB::new(&client);\n\n    let result = vectors_db.list_documents(\n        \"<DATABASE_ID>\",\n        \"<COLLECTION_ID>\",\n        Some(vec![Query::limit(10).to_string()]),\n        None, // transactionId (optional)\n        None, // total (optional)\n        None, // ttl (optional)\n    ).await?;\n\n    println!(\"{:?}\", result);\n    Ok(())\n}\n```\n```bash\nappwrite vectors-db list-documents \\\n    --database-id <DATABASE_ID> \\\n    --collection-id <COLLECTION_ID> \\\n    --queries '{\"method\":\"limit\",\"values\":[10]}'\n```\n{% /multicode %}\n{% /section %}\n\n{% section #next-steps step=5 title=\"Next steps\" %}\nYou now have a database, a collection, and a document holding an embedding with its metadata. From here:\n\n- Generate vectors from your text instead of hardcoding them with [embeddings](/docs/products/databases/vectorsdb/embeddings).\n- Find the documents closest to a query vector with [vector search](/docs/products/databases/vectorsdb/vector-search).\n\n{% arrow_link href=\"/docs/products/databases/vectorsdb/vector-search\" %}\nRun vector search\n{% /arrow_link %}\n{% /section %}\n";
